mapper.select:
SELECT so.* FROM sales_order so WHERE so.tenant_id = #{tenantId} AND so.deleted = 0
AND so.store_id = #{storeId}
AND so.store_id IN
#{allowedStoreId}
AND 1 = 0
AND so.order_status = #{orderStatus}
AND so.pay_status = #{payStatus}
AND ( so.order_no LIKE CONCAT('%', #{keyword}, '%') OR so.subject LIKE CONCAT('%', #{keyword}, '%') )
AND EXISTS ( SELECT 1 FROM sales_order_item soi WHERE soi.tenant_id = so.tenant_id AND soi.order_no = so.order_no AND ( soi.delivery_status IN
#{status}
OR soi.delivery_status IS NULL
) )
AND EXISTS ( SELECT 1 FROM sales_order_item soi WHERE soi.tenant_id = so.tenant_id AND soi.order_no = so.order_no AND (soi.delivery_status IS NULL OR soi.delivery_status IN ('PENDING', 'DELIVERING')) )
AND EXISTS ( SELECT 1 FROM sales_order_item soi WHERE soi.tenant_id = so.tenant_id AND soi.order_no = so.order_no ) AND NOT EXISTS ( SELECT 1 FROM sales_order_item soi WHERE soi.tenant_id = so.tenant_id AND soi.order_no = so.order_no AND (soi.delivery_status IS NULL OR soi.delivery_status NOT IN ('DELIVERED', 'CONFIRMED')) )
AND ( so.pay_status = 'FAILED' OR EXISTS ( SELECT 1 FROM sales_order_item soi WHERE soi.tenant_id = so.tenant_id AND soi.order_no = so.order_no AND soi.delivery_status IN ('FAILED', 'REVOKE_FAILED') ) )
ORDER BY so.create_time DESC
